//! The one error type, whose every refusal has a stable name ([`Error::code`]).
use crate::Target;
use std::fmt;

/// Why a key, signature, record, feed or configuration was refused. No variant carries key
/// material: a private key's text never reaches a message.
#[derive(Debug)]
pub enum Error {
    /// A private key that is not Sparkle's exported form: base64 of a 32-byte seed.
    MalformedKey(&'static str),
    /// Sparkle's older 96-byte private key (an expanded orlp key and its public key). Its seed
    /// cannot be recovered, so it cannot sign here; export a key generated by Sparkle 2.
    LegacyKey,
    /// A public key that is not base64 of 32 bytes.
    MalformedPublicKey,
    /// A signature that is not base64 of 64 bytes.
    MalformedSignature,
    /// A signing key whose public key is not the one `release/update.json` commits.
    KeyMismatch,
    /// Bytes whose signature does not verify against the public key.
    BadSignature,
    /// A file whose length is not the length its record or feed item states.
    LengthMismatch {
        expected: u64,
        actual: u64,
    },
    /// An update record that is not the current shape or is inconsistent with itself.
    MalformedRecord(String),
    /// A feed that is not a Sparkle-format RSS appcast this crate can read.
    MalformedAppcast(String),
    /// `release/update.json` that is not the current shape.
    MalformedConfig(String),
    /// The published-release list or withdrawal list that is not the current shape.
    MalformedInput(String),
    /// Two records for one release, or two releases with one version.
    DuplicateRelease(String),
    /// Build numbers that do not strictly rise with SemVer version order within a target.
    BuildNotRising {
        target: Target,
        earlier: String,
        earlier_build: u64,
        later: String,
        later_build: u64,
    },
    /// A record whose release, or whose archive in that release, is not published.
    UnpublishedAsset {
        tag: String,
        file: String,
    },
    /// A published asset whose byte length is not the record's.
    AssetLengthMismatch {
        tag: String,
        file: String,
        record: u64,
        published: u64,
    },
    /// A record signed by a key other than the committed public key.
    RecordKeyMismatch {
        tag: String,
    },
    /// A directory that is not a Linux payload: no readable `build.json` naming this build, or no
    /// executable where the payload should hold one.
    NotPayload(String),
    /// A request the payload updater's fetch could not complete: the network, TLS, an HTTP status
    /// other than 200 or a refused URL.
    Fetch(String),
    /// A download longer than its feed item states, or than the updater's absolute cap.
    Oversize {
        limit: u64,
    },
    /// An archive entry the payload updater refuses to extract: an absolute path, `..`, a link
    /// that could leave the payload, a device or other special file, or past the size caps.
    UnsafeArchive(String),
    /// An extracted payload whose `build.json` does not name the feed item's version, build and
    /// target.
    BuildMismatch(String),
    /// The payload could not be swapped for the new one; the installed payload is unchanged.
    InstallFailed(String),
    /// The work was cancelled, as quitting cancels a download.
    Cancelled,
    Io(std::io::Error),
}

impl Error {
    /// The refusal's stable name.
    pub fn code(&self) -> &'static str {
        match self {
            Error::MalformedKey(_) => "malformed-key",
            Error::LegacyKey => "legacy-key",
            Error::MalformedPublicKey => "malformed-public-key",
            Error::MalformedSignature => "malformed-signature",
            Error::KeyMismatch => "key-mismatch",
            Error::BadSignature => "bad-signature",
            Error::LengthMismatch { .. } => "length-mismatch",
            Error::MalformedRecord(_) => "malformed-record",
            Error::MalformedAppcast(_) => "malformed-appcast",
            Error::MalformedConfig(_) => "malformed-config",
            Error::MalformedInput(_) => "malformed-input",
            Error::DuplicateRelease(_) => "duplicate-release",
            Error::BuildNotRising { .. } => "build-not-rising",
            Error::UnpublishedAsset { .. } => "unpublished-asset",
            Error::AssetLengthMismatch { .. } => "asset-length-mismatch",
            Error::RecordKeyMismatch { .. } => "record-key-mismatch",
            Error::NotPayload(_) => "not-a-payload",
            Error::Fetch(_) => "fetch-failed",
            Error::Oversize { .. } => "oversize",
            Error::UnsafeArchive(_) => "unsafe-archive",
            Error::BuildMismatch(_) => "build-mismatch",
            Error::InstallFailed(_) => "install-failed",
            Error::Cancelled => "cancelled",
            Error::Io(_) => "io",
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: ", self.code())?;
        match self {
            Error::MalformedKey(why) => write!(
                f,
                "the private key is not Sparkle's exported form (base64 of a 32-byte seed): {why}"
            ),
            Error::LegacyKey => f.write_str(
                "the private key is Sparkle's older 96-byte form, whose seed cannot be recovered; \
                 use a key generated by Sparkle 2's generate_keys",
            ),
            Error::MalformedPublicKey => f.write_str("a public key must be base64 of 32 bytes"),
            Error::MalformedSignature => f.write_str("a signature must be base64 of 64 bytes"),
            Error::KeyMismatch => f.write_str(
                "the signing key's public key is not the public key in release/update.json",
            ),
            Error::BadSignature => f.write_str("the Ed25519 signature does not verify"),
            Error::LengthMismatch { expected, actual } => {
                write!(f, "expected {expected} bytes, found {actual}")
            }
            Error::MalformedRecord(why)
            | Error::MalformedAppcast(why)
            | Error::MalformedConfig(why)
            | Error::MalformedInput(why)
            | Error::DuplicateRelease(why)
            | Error::NotPayload(why)
            | Error::Fetch(why)
            | Error::UnsafeArchive(why)
            | Error::BuildMismatch(why)
            | Error::InstallFailed(why) => f.write_str(why),
            Error::Oversize { limit } => write!(f, "the download is longer than {limit} bytes"),
            Error::Cancelled => f.write_str("cancelled"),
            Error::BuildNotRising {
                target,
                earlier,
                earlier_build,
                later,
                later_build,
            } => write!(
                f,
                "{target}: {later} has build {later_build}, which does not rise above {earlier}'s \
                 build {earlier_build}"
            ),
            Error::UnpublishedAsset { tag, file } => write!(
                f,
                "{tag}: {file} is not a published asset; withdraw the release or publish it"
            ),
            Error::AssetLengthMismatch {
                tag,
                file,
                record,
                published,
            } => write!(
                f,
                "{tag}: {file} is {published} bytes as published but {record} in its record"
            ),
            Error::RecordKeyMismatch { tag } => write!(
                f,
                "{tag}: the record is signed by a key other than release/update.json's; withdraw \
                 releases signed by a retired key"
            ),
            Error::Io(error) => write!(f, "{error}"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Error::Io(error) => Some(error),
            _ => None,
        }
    }
}

impl From<std::io::Error> for Error {
    fn from(error: std::io::Error) -> Self {
        Error::Io(error)
    }
}

pub type Result<T> = std::result::Result<T, Error>;
